def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = {r for r in range(h) if grid[r].count(5) > w // 2}
    sep_cols = {c for c in range(w) if sum(grid[r][c] == 5 for r in range(h)) > h // 2}
    markers = [(r, c) for r in sep_rows for c in sep_cols if grid[r][c] != 5]
    if markers:
        r0, r1 = min(r for r, c in markers), max(r for r, c in markers)
        c0, c1 = min(c for r, c in markers), max(c for r, c in markers)
        return [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    return grid
